import { useState, useEffect, useRef } from "react";
(() => {
  if (document.getElementById("tt-css")) return;
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = "https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,700;1,400;1,500&family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500;9..40,600;9..40,700&display=swap";
  document.head.appendChild(link);
  const s = document.createElement("style");
  s.id = "tt-css";
  s.textContent = `
    :root{--cream:#F5F0E8;--cream-dark:#EDE6D8;--black:#1A1A1A;--black-soft:#2D2D2D;--caramel:#B8860B;--caramel-light:#D4A843;--warm-gray:#8C8578;--warm-gray-light:#B5AFA5;--led-warm:#FFD89B;--led-glow:#FFCC66;--white:#FEFCF8;--burnt-orange:#C4703F;--olive:#7A8B6F;--dusty-rose:#C1908E;--muted-blue:#7B8FA1;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',-apple-system,sans-serif}
    *,*::before,*::after{margin:0;padding:0;box-sizing:border-box}html{scroll-behavior:smooth}body{background:var(--cream);color:var(--black);font-family:var(--sans);overflow-x:hidden;-webkit-font-smoothing:antialiased}::selection{background:var(--caramel-light);color:var(--white)}
    @keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}@keyframes breathe{0%,100%{opacity:.4;transform:scale(1)}50%{opacity:.85;transform:scale(1.12)}}@keyframes nfcPulse{0%{transform:translate(-50%,-50%) scale(.3);opacity:.9}100%{transform:translate(-50%,-50%) scale(2.6);opacity:0}}@keyframes waveBar{0%,100%{transform:scaleY(.1);opacity:.25}50%{transform:scaleY(1);opacity:1}}@keyframes shimmerBtn{0%{background-position:-300% center}100%{background-position:300% center}}@keyframes floatUp{0%,100%{transform:translateY(0) rotate(-5deg)}50%{transform:translateY(-22px) rotate(-5deg)}}@keyframes particleRise{0%{transform:translateY(0) scale(1);opacity:.75}100%{transform:translateY(-160px) scale(.2);opacity:0}}@keyframes glowPulse{0%,100%{opacity:.4}50%{opacity:1}}@keyframes discSlideIn{from{opacity:0;transform:translateX(-200px) translateY(20px)}to{opacity:1;transform:translateX(0) translateY(0)}}@keyframes strokeIn{from{stroke-dashoffset:500}to{stroke-dashoffset:0}}@keyframes fadeInUp{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:translateY(0)}}@keyframes countUp{0%{opacity:0;transform:translateY(6px)}100%{opacity:1;transform:translateY(0)}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
  `;
  document.head.appendChild(s);
})();

const discs=[{id:1,name:"Nuestra Canción",color:"#C4703F",desc:"La canción que define tu historia."},{id:2,name:"Viajes",color:"#D4A843",desc:"Soundtracks de los caminos recorridos."},{id:3,name:"Recuerdos",color:"#8C8578",desc:"Momentos que merecen volver a sonar."},{id:4,name:"Días Felices",color:"#7A8B6F",desc:"Las canciones de tus mejores días."},{id:5,name:"Éxitos",color:"#B8860B",desc:"Tus temas favoritos, siempre a mano."},{id:6,name:"Relajación",color:"#7B8FA1",desc:"Música para bajar el ritmo."},{id:7,name:"Entreno",color:"#C1908E",desc:"Energía pura en cada disco."},{id:8,name:"Rock Clásico",color:"#5C4033",desc:"Los clásicos que nunca pasan de moda."},{id:9,name:"Favoritas",color:"#6B705C",desc:"Tu selección personal definitiva."}];
const faqs=[{q:"¿Cómo funciona el NFC?",a:"Cada disco tiene un chip NFC pasivo. Al acercarlo al reproductor, TapTunes identifica el disco y reproduce la canción o playlist asignada automáticamente."},{q:"¿Necesito internet para usarlo?",a:"No. La música se almacena en la memoria interna del dispositivo (128MB). Cargás las canciones por USB-C y funciona de forma independiente."},{q:"¿Puedo elegir mis propias canciones?",a:"Sí. Conectás TapTunes a tu computadora por USB-C, cargás los archivos de audio y asignás cada canción a un disco."},{q:"¿Cuántos discos vienen incluidos?",a:"El Starter Kit incluye 9 discos NFC personalizables, cada uno con su categoría temática."},{q:"¿Puedo comprar discos extra?",a:"Sí. Próximamente ofreceremos packs de discos adicionales y ediciones especiales temáticas."},{q:"¿Cuánto dura la batería?",a:"Hasta 8 horas de reproducción continua con una carga completa vía USB-C."},{q:"¿Tiene garantía?",a:"Sí. TapTunes incluye garantía de 90 días contra defectos de fabricación."},{q:"¿Hacen envíos?",a:"Sí. Realizamos envíos a todo Uruguay. Los detalles de envío se coordinan al confirmar tu pedido."},{q:"¿Puedo regalarlo ya configurado?",a:"Sí. En la personalización podés indicar las canciones que querés cargar y lo enviamos listo para usar."}];
const useCases=["Regalo de pareja","Cumpleaños","Aniversario","Regalo para padres","Navidad","San Valentín","Decoración","Entrenamiento","Viajes","Amigos"];

function useInView(threshold=0.15){const ref=useRef(null);const[v,setV]=useState(false);useEffect(()=>{const el=ref.current;if(!el)return;const obs=new IntersectionObserver(([e])=>{if(e.isIntersecting){setV(true);obs.unobserve(el);}},{threshold});obs.observe(el);return()=>obs.disconnect();},[threshold]);return[ref,v];}
function useReducedMotion(){const[r]=useState(()=>typeof window!=="undefined"&&window.matchMedia?.("(prefers-reduced-motion: reduce)").matches);return r;}

function Turntable({size=420,spinning=true,labelColor="#B8860B",glowIntensity=0.6,showControls=true,armPosition="playing",discVisible=true,discAnimating=false}){
  const spinRef=useRef(null),angleRef=useRef(0),rafRef=useRef(null),reduced=useReducedMotion();
  useEffect(()=>{if(reduced||!spinning||!spinRef.current){cancelAnimationFrame(rafRef.current);return;}const a=()=>{angleRef.current=(angleRef.current+0.22)%360;if(spinRef.current)spinRef.current.setAttribute("transform",`rotate(${angleRef.current.toFixed(2)},220,222)`);rafRef.current=requestAnimationFrame(a);};rafRef.current=requestAnimationFrame(a);return()=>cancelAnimationFrame(rafRef.current);},[spinning,reduced]);
  const u="tt";
  return(
    <svg width={size} height={size} viewBox="0 0 440 440" fill="none" style={{overflow:"visible",willChange:"transform"}}>
      <defs>
        <radialGradient id={`${u}-base`} cx="50%" cy="38%" r="70%"><stop offset="0%" stopColor="#FEFCF8"/><stop offset="100%" stopColor="#E8E0D0"/></radialGradient>
        <radialGradient id={`${u}-platter`} cx="40%" cy="35%" r="65%"><stop offset="0%" stopColor="#2A2A2A"/><stop offset="100%" stopColor="#080808"/></radialGradient>
        <radialGradient id={`${u}-label`} cx="35%" cy="32%" r="65%"><stop offset="0%" stopColor={labelColor}/><stop offset="100%" stopColor={labelColor} stopOpacity="0.6"/></radialGradient>
        <linearGradient id={`${u}-hl`} x1="10%" y1="10%" x2="90%" y2="90%"><stop offset="0%" stopColor="white" stopOpacity="0.1"/><stop offset="45%" stopColor="white" stopOpacity="0.025"/><stop offset="100%" stopColor="white" stopOpacity="0"/></linearGradient>
        <radialGradient id={`${u}-glow`} cx="50%" cy="50%" r="50%"><stop offset="72%" stopColor="transparent"/><stop offset="100%" stopColor={`rgba(255,204,102,${glowIntensity*0.7})`}/></radialGradient>
        <filter id={`${u}-shadow`} x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="8" stdDeviation="16" floodColor="rgba(0,0,0,0.18)"/></filter>
      </defs>
      <rect x="8" y="8" width="424" height="424" rx="20" fill={`url(#${u}-base)`} stroke="#D0C8BC" strokeWidth="1" filter={`url(#${u}-shadow)`}/>
      <rect x="14" y="14" width="412" height="412" rx="17" fill="none" stroke="rgba(255,255,255,0.6)" strokeWidth="0.5"/>
      {[[30,30],[410,30],[30,410],[410,410]].map(([cx,cy],i)=>(<g key={i}><circle cx={cx} cy={cy} r="8" fill="#CAC2B6" stroke="#B0A898" strokeWidth="1"/><circle cx={cx} cy={cy} r="4" fill="#B8B0A4"/><line x1={cx-4.5} y1={cy} x2={cx+4.5} y2={cy} stroke="#8A8278" strokeWidth="1.2" strokeLinecap="round"/><line x1={cx} y1={cy-4.5} x2={cx} y2={cy+4.5} stroke="#8A8278" strokeWidth="1.2" strokeLinecap="round"/></g>))}
      <text x="220" y="50" textAnchor="middle" fontFamily="DM Sans,sans-serif" fontSize="10.5" fontWeight="700" letterSpacing="3.5" fill="#8C8578" opacity="0.85">TAPTUNES™</text>
      <circle cx="220" cy="222" r="162" fill="#101010" stroke="#1E1E1E" strokeWidth="1.5"/>
      <g style={{opacity:discVisible?1:0,transition:discAnimating?"none":"opacity 0.6s ease",animation:discAnimating?"discSlideIn 0.9s cubic-bezier(0.25,0.46,0.45,0.94) forwards":"none"}}>
        <g ref={spinRef}>
          <circle cx="220" cy="222" r="152" fill={`url(#${u}-platter)`}/>
          {Array.from({length:20},(_,i)=>{const r=58+i*4.7;return(<circle key={i} cx="220" cy="222" r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="0.6" opacity={0.5+(i%4)*0.15}/>);})}
          <circle cx="220" cy="222" r="152" fill={`url(#${u}-hl)`}/>
          <circle cx="220" cy="222" r="50" fill={`url(#${u}-label)`}/>
          <circle cx="220" cy="222" r="50" fill="none" stroke="rgba(255,255,255,0.18)" strokeWidth="0.8"/>
          <ellipse cx="208" cy="212" rx="16" ry="9" fill="rgba(255,255,255,0.1)" transform="rotate(-30,208,212)"/>
          <text x="220" y="219" textAnchor="middle" fontFamily="DM Sans,sans-serif" fontSize="7.5" fontWeight="700" letterSpacing="2.5" fill="rgba(255,255,255,0.92)">TAPTUNES</text>
          <text x="220" y="230" textAnchor="middle" fontFamily="DM Sans,sans-serif" fontSize="5" letterSpacing="1.5" fill="rgba(255,255,255,0.55)">NFC PLAYER</text>
          <circle cx="220" cy="222" r="7" fill="#080808" stroke="#2A2A2A" strokeWidth="0.8"/><circle cx="220" cy="222" r="3" fill="#1A1A1A"/>
        </g>
      </g>
      <circle cx="220" cy="222" r="155" fill={`url(#${u}-glow)`} style={{animation:"glowPulse 3s ease-in-out infinite"}}/>
      <circle cx="368" cy="76" r="16" fill="#CAC2B6" stroke="#A89E90" strokeWidth="1.5"/><circle cx="368" cy="76" r="9" fill="#B8B0A4"/><circle cx="368" cy="76" r="4" fill="#8A8278"/>
      {armPosition==="playing"?(<g><line x1="368" y1="76" x2="290" y2="184" stroke="rgba(0,0,0,0.15)" strokeWidth="7" strokeLinecap="round"/><line x1="368" y1="76" x2="290" y2="184" stroke="#C0B8AC" strokeWidth="5.5" strokeLinecap="round"/><line x1="368" y1="76" x2="290" y2="184" stroke="#D8D0C4" strokeWidth="3" strokeLinecap="round"/><circle cx="290" cy="184" r="4" fill="#C8C0B4"/><line x1="290" y1="184" x2="274" y2="206" stroke="#C0B8AC" strokeWidth="4" strokeLinecap="round"/><rect x="266" y="202" width="17" height="9" rx="2.5" fill="#C4703F"/><line x1="275" y1="211" x2="275" y2="219" stroke="#DDD8D0" strokeWidth="1.5" strokeLinecap="round"/><circle cx="275" cy="221" r="2.5" fill="#C4703F"/><circle cx="275" cy="221" r="1" fill="#8A3018"/></g>):(<g><line x1="368" y1="76" x2="340" y2="88" stroke="#C0B8AC" strokeWidth="5" strokeLinecap="round"/><line x1="340" y1="88" x2="326" y2="110" stroke="#C0B8AC" strokeWidth="4" strokeLinecap="round"/><rect x="318" y="106" width="17" height="9" rx="2.5" fill="#C4703F"/></g>)}
      {showControls&&(<g><line x1="68" y1="390" x2="372" y2="390" stroke="#C8C0B4" strokeWidth="1.5" strokeLinecap="round"/><line x1="68" y1="390" x2="188" y2="390" stroke="#B8860B" strokeWidth="2" strokeLinecap="round"/><circle cx="188" cy="390" r="4.5" fill="#B8860B" style={{opacity:discVisible?1:0,transition:"opacity 0.4s ease 2.8s"}}/><text x="68" y="406" fontFamily="DM Sans,sans-serif" fontSize="9" fill="#8C8578">0:00</text><text x="372" y="406" textAnchor="end" fontFamily="DM Sans,sans-serif" fontSize="9" fill="#8C8578">4:30</text><g transform="translate(178,358)" style={{cursor:"pointer",opacity:0.65}}><polygon points="0,0 -10,6 0,12" fill="#8C8578"/></g><g transform="translate(220,355)" style={{cursor:"pointer"}}><rect x="-10" y="0" width="7" height="16" rx="2" fill="#1A1A1A"/><rect x="3" y="0" width="7" height="16" rx="2" fill="#1A1A1A"/></g><g transform="translate(262,358)" style={{cursor:"pointer",opacity:0.65}}><polygon points="0,0 10,6 0,12" fill="#8C8578"/></g></g>)}
    </svg>
  );
}

function VinylDisc({size=140,color="#C4703F",number="01",spinning=false}){
  const spinRef=useRef(null),angleRef=useRef(Math.random()*360),rafRef=useRef(null),reduced=useReducedMotion();
  useEffect(()=>{if(reduced||!spinning||!spinRef.current){cancelAnimationFrame(rafRef.current);return;}const a=()=>{angleRef.current=(angleRef.current+0.45)%360;if(spinRef.current)spinRef.current.setAttribute("transform",`rotate(${angleRef.current.toFixed(2)},${size/2},${size/2})`);rafRef.current=requestAnimationFrame(a);};rafRef.current=requestAnimationFrame(a);return()=>cancelAnimationFrame(rafRef.current);},[spinning,size,reduced]);
  const cx=size/2,cy=size/2,outerR=size/2-1,labelR=outerR*0.31,uid=`vd-${number}`;
  return(
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} fill="none" style={{overflow:"visible"}}>
      <defs><radialGradient id={`${uid}-bg`} cx="42%" cy="38%" r="65%"><stop offset="0%" stopColor="#282828"/><stop offset="100%" stopColor="#0A0A0A"/></radialGradient><linearGradient id={`${uid}-hl`} x1="5%" y1="5%" x2="95%" y2="95%"><stop offset="0%" stopColor="white" stopOpacity="0.14"/><stop offset="50%" stopColor="white" stopOpacity="0.03"/><stop offset="100%" stopColor="white" stopOpacity="0"/></linearGradient><radialGradient id={`${uid}-lbl`} cx="35%" cy="30%" r="70%"><stop offset="0%" stopColor={color}/><stop offset="100%" stopColor={color} stopOpacity="0.65"/></radialGradient></defs>
      <g ref={spinRef}><circle cx={cx} cy={cy} r={outerR} fill={`url(#${uid}-bg)`}/>{Array.from({length:13},(_,i)=>{const r=labelR+5+i*((outerR-labelR-7)/13);return(<circle key={i} cx={cx} cy={cy} r={r} fill="none" stroke="rgba(255,255,255,0.065)" strokeWidth="0.55"/>);})}<circle cx={cx} cy={cy} r={outerR} fill={`url(#${uid}-hl)`}/><circle cx={cx} cy={cy} r={labelR} fill={`url(#${uid}-lbl)`}/><circle cx={cx} cy={cy} r={labelR} fill="none" stroke="rgba(255,255,255,0.2)" strokeWidth="0.6"/><text x={cx} y={cy+labelR*0.18} textAnchor="middle" fontFamily="DM Sans,sans-serif" fontSize={labelR*0.58} fontWeight="700" fill="rgba(255,255,255,0.95)">{number}</text><circle cx={cx} cy={cy} r={outerR*0.046} fill="#060606" stroke="#282828" strokeWidth="0.5"/></g>
      <circle cx={cx} cy={cy} r={outerR} fill="none" stroke="rgba(255,255,255,0.04)" strokeWidth="1"/>
    </svg>
  );
}

function AudioWaveform({bars=26,color="var(--caramel)",height=44,active=true}){const d=useRef(null);if(!d.current)d.current=Array.from({length:bars},()=>({dur:(0.55+Math.random()*0.75).toFixed(2),del:(Math.random()*0.9).toFixed(2),maxH:Math.round(30+Math.random()*70)}));return(<div style={{display:"flex",alignItems:"center",gap:"2.5px",height,flexShrink:0}}>{d.current.map((b,i)=>(<div key={i} style={{width:3,borderRadius:2,height:`${b.maxH}%`,background:color,transformOrigin:"bottom",animation:active?`waveBar ${b.dur}s ease-in-out ${b.del}s infinite`:"none",willChange:"transform",opacity:active?1:0.2,transition:"opacity 0.4s ease"}}/>))}</div>);}
function NfcWaves({size=64,color="var(--caramel-light)",active=true}){return(<div style={{position:"relative",width:size,height:size}}>{[0,1,2].map(i=>(<div key={i} style={{position:"absolute",top:"50%",left:"50%",width:size*(0.35+i*0.22),height:size*(0.35+i*0.22),borderRadius:"50%",border:`1.5px solid ${color}`,transform:"translate(-50%,-50%)",animation:active?`nfcPulse 2.2s ease-out ${i*0.55}s infinite`:"none",willChange:"transform,opacity"}}/>))}<div style={{position:"absolute",top:"50%",left:"50%",transform:"translate(-50%,-50%)",width:size*0.22,height:size*0.22,borderRadius:"50%",background:color,opacity:0.35}}/></div>);}
function MusicParticles({count=14,active=true}){const p=useRef(null);if(!p.current)p.current=Array.from({length:count},(_,i)=>({sym:["♪","♫","♬","♩"][i%4],left:5+Math.random()*88,del:(Math.random()*4).toFixed(2),dur:(2.8+Math.random()*2.2).toFixed(2),sz:11+Math.random()*10,op:0.35+Math.random()*0.45}));return(<div style={{position:"absolute",inset:0,pointerEvents:"none",overflow:"hidden"}}>{p.current.map((pt,i)=>(<span key={i} style={{position:"absolute",left:`${pt.left}%`,bottom:"8%",fontSize:pt.sz,color:"var(--caramel-light)",opacity:active?pt.op:0,animation:active?`particleRise ${pt.dur}s ease-out ${pt.del}s infinite`:"none",willChange:"transform,opacity",pointerEvents:"none",userSelect:"none"}}>{pt.sym}</span>))}</div>);}

function IconZap({size=40,color="#FEFCF8",animated=false}){return(<svg width={size} height={size} viewBox="0 0 40 40" fill="none"><polyline points="23,4 10,22 20,22 17,36 30,18 20,18 23,4" stroke={color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" style={animated?{animation:"strokeIn 1s ease-out forwards"}:{}}/></svg>);}
function IconLight({size=40,color="#FEFCF8",animated=false}){const s=animated?{animation:"strokeIn 1s ease-out 0.1s forwards"}:{};return(<svg width={size} height={size} viewBox="0 0 40 40" fill="none"><circle cx="20" cy="17" r="7" stroke={color} strokeWidth="2" style={s}/><path d="M16,24 L14,32 L26,32 L24,24" stroke={color} strokeWidth="2" strokeLinejoin="round" style={s}/><line x1="20" y1="5" x2="20" y2="7" stroke={color} strokeWidth="2" strokeLinecap="round"/><line x1="8" y1="10" x2="10" y2="11.5" stroke={color} strokeWidth="2" strokeLinecap="round"/><line x1="32" y1="10" x2="30" y2="11.5" stroke={color} strokeWidth="2" strokeLinecap="round"/></svg>);}
function IconDisc({size=40,color="#FEFCF8",animated=false}){const s=animated?{animation:"strokeIn 1s ease-out 0.15s forwards"}:{};return(<svg width={size} height={size} viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="14" stroke={color} strokeWidth="2" style={s}/><circle cx="20" cy="20" r="9" stroke={color} strokeWidth="1.5" opacity="0.5" style={s}/><circle cx="20" cy="20" r="4" stroke={color} strokeWidth="2" style={s}/><circle cx="20" cy="20" r="1.5" fill={color}/></svg>);}
function IconUSB({size=40,color="#FEFCF8",animated=false}){const s=animated?{animation:"strokeIn 1.2s ease-out forwards"}:{};return(<svg width={size} height={size} viewBox="0 0 40 40" fill="none"><rect x="14" y="6" width="12" height="8" rx="2" stroke={color} strokeWidth="2" style={s}/><line x1="20" y1="14" x2="20" y2="26" stroke={color} strokeWidth="2" strokeLinecap="round" style={s}/><path d="M13,26 Q13,34 20,34 Q27,34 27,26" stroke={color} strokeWidth="2" strokeLinecap="round" style={s}/><circle cx="13" cy="26" r="2.5" fill={color} opacity="0.7"/><circle cx="27" cy="26" r="2.5" fill={color} opacity="0.7"/></svg>);}
function IconChip({size=40,color="#FEFCF8",animated=false}){const s=animated?{animation:"strokeIn 1s ease-out 0.1s forwards"}:{};return(<svg width={size} height={size} viewBox="0 0 40 40" fill="none"><rect x="12" y="12" width="16" height="16" rx="3" stroke={color} strokeWidth="2" style={s}/><rect x="16" y="16" width="8" height="8" rx="1.5" stroke={color} strokeWidth="1.5" opacity="0.6" style={s}/></svg>);}
function IconDiscs({size=40,color="#FEFCF8",animated=false}){const s=animated?{animation:"strokeIn 1s ease-out 0.1s forwards"}:{};return(<svg width={size} height={size} viewBox="0 0 40 40" fill="none"><circle cx="20" cy="22" r="12" stroke={color} strokeWidth="2" style={s}/><circle cx="20" cy="22" r="4" stroke={color} strokeWidth="1.5" style={s}/><circle cx="20" cy="22" r="1.5" fill={color}/></svg>);}

function ScrollProgressBar(){const b=useRef(null);useEffect(()=>{let r;const o=()=>{cancelAnimationFrame(r);r=requestAnimationFrame(()=>{const t=document.documentElement.scrollHeight-window.innerHeight;const p=t>0?(window.scrollY/t)*100:0;if(b.current)b.current.style.width=`${p}%`;});};window.addEventListener("scroll",o,{passive:true});return()=>{window.removeEventListener("scroll",o);cancelAnimationFrame(r);};},[]);return(<div style={{position:"fixed",top:0,left:0,right:0,height:2,zIndex:9999,background:"rgba(184,134,11,0.12)"}}><div ref={b} style={{height:"100%",width:"0%",background:"linear-gradient(90deg,var(--caramel),var(--caramel-light))",transition:"width 0.1s linear",boxShadow:"0 0 8px rgba(212,168,67,0.6)"}}/></div>);}
function WaveDivider({toColor="#1A1A1A",flip=false}){return(<div style={{display:"block",lineHeight:0,overflow:"hidden",transform:flip?"rotate(180deg)":"none"}}><svg viewBox="0 0 1440 72" preserveAspectRatio="none" style={{width:"100%",height:56,display:"block"}}><path d="M0,36 C240,72 480,0 720,36 C960,72 1200,0 1440,36 L1440,72 L0,72 Z" fill={toColor}/></svg></div>);}

function Navbar({scrolled}){return(<nav style={{position:"fixed",top:0,left:0,right:0,zIndex:200,background:scrolled?"rgba(245,240,232,0.96)":"transparent",backdropFilter:scrolled?"blur(24px)":"none",borderBottom:scrolled?"1px solid rgba(26,26,26,0.06)":"none",transition:"all 0.5s cubic-bezier(0.4,0,0.2,1)",padding:"0 clamp(20px,5vw,80px)"}}><div style={{maxWidth:1280,margin:"0 auto",display:"flex",alignItems:"center",justifyContent:"space-between",height:scrolled?60:76,transition:"height 0.4s ease"}}><div style={{display:"flex",alignItems:"center",gap:8}}><svg width="28" height="28" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="12.5" stroke="var(--black)" strokeWidth="1.5"/><circle cx="14" cy="14" r="6" stroke="var(--black)" strokeWidth="1"/><circle cx="14" cy="14" r="2" fill="var(--black)"/></svg><span style={{fontFamily:"var(--sans)",fontWeight:700,fontSize:15,letterSpacing:"0.12em"}}>TAPTUNES<sup style={{fontSize:8,verticalAlign:"super"}}>™</sup></span></div><a href="#comprar" style={{textDecoration:"none",background:"var(--black)",color:"var(--white)",padding:"10px 24px",fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.12em",textTransform:"uppercase",transition:"background 0.3s ease"}} onMouseEnter={e=>e.currentTarget.style.background="var(--caramel)"} onMouseLeave={e=>e.currentTarget.style.background="var(--black)"}>Reservar</a></div></nav>);}

function Hero(){const tRef=useRef(null);const[tt,setTt]=useState(false);const[disc,setDisc]=useState(false);const[anim,setAnim]=useState(false);const[play,setPlay]=useState(false);const[badge,setBadge]=useState(false);const[title,setTitle]=useState(false);const[sub,setSub]=useState(false);const[ctas,setCtas]=useState(false);const isMobile=typeof window!=="undefined"&&window.innerWidth<768;
  useEffect(()=>{const t=[setTimeout(()=>setTt(true),200),setTimeout(()=>setBadge(true),350),setTimeout(()=>setTitle(true),650),setTimeout(()=>setSub(true),950),setTimeout(()=>setCtas(true),1200),setTimeout(()=>{setAnim(true);setDisc(true);},1600),setTimeout(()=>{setAnim(false);setPlay(true);},2500)];return()=>t.forEach(clearTimeout);},[]);
  useEffect(()=>{if(isMobile)return;let r;const o=()=>{cancelAnimationFrame(r);r=requestAnimationFrame(()=>{if(tRef.current)tRef.current.style.transform=`translateY(${window.scrollY*0.14}px)`;});};window.addEventListener("scroll",o,{passive:true});return()=>{window.removeEventListener("scroll",o);cancelAnimationFrame(r);};},[isMobile]);
  return(
    <section style={{minHeight:"100vh",padding:"100px clamp(20px,5vw,80px) 80px",position:"relative",overflow:"hidden",display:"flex",alignItems:"center"}}>
      <div style={{position:"absolute",inset:0,pointerEvents:"none"}}><div style={{position:"absolute",inset:0,background:"var(--cream)"}}/><div style={{position:"absolute",top:"15%",left:"10%",width:560,height:560,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,216,155,0.22) 0%,transparent 68%)",animation:"breathe 8s ease-in-out infinite"}}/><div style={{position:"absolute",top:"-5%",right:"8%",width:420,height:420,borderRadius:"50%",background:"radial-gradient(circle,rgba(212,168,67,0.11) 0%,transparent 70%)",animation:"breathe 11s ease-in-out 2s infinite"}}/></div>
      <MusicParticles count={isMobile?6:14} active={play}/>
      <div style={{maxWidth:1200,width:"100%",margin:"0 auto",display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr",gap:isMobile?48:64,alignItems:"center",position:"relative",zIndex:1}}>
        <div style={{textAlign:isMobile?"center":"left"}}>
          <div style={{opacity:badge?1:0,transform:badge?"translateY(0)":"translateY(16px)",transition:"all 0.7s cubic-bezier(0.4,0,0.2,1)",marginBottom:28}}><span style={{display:"inline-flex",alignItems:"center",gap:8,fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)",padding:"7px 18px",border:"1px solid rgba(184,134,11,0.35)",background:"rgba(212,168,67,0.06)"}}><NfcWaves size={18} active={play}/>Reproductor NFC</span></div>
          <div style={{opacity:title?1:0,transform:title?"translateY(0)":"translateY(32px)",transition:"all 0.9s cubic-bezier(0.4,0,0.2,1)"}}><h1 style={{fontFamily:"var(--serif)",fontSize:"clamp(44px,7vw,86px)",fontWeight:400,lineHeight:1.06,letterSpacing:"-0.02em",marginBottom:24}}>Tu música,<br/><em style={{fontStyle:"italic",color:"var(--caramel)"}}>en un solo toque.</em></h1></div>
          <div style={{opacity:sub?1:0,transform:sub?"translateY(0)":"translateY(24px)",transition:"all 0.9s cubic-bezier(0.4,0,0.2,1)",marginBottom:40}}><p style={{fontFamily:"var(--sans)",fontSize:"clamp(15px,1.8vw,17px)",color:"var(--warm-gray)",lineHeight:1.75,maxWidth:460}}>Acercá un disco y reviví una canción, una playlist o un recuerdo al instante. Un reproductor NFC con luz ambiental y diseño premium.</p></div>
          <div style={{opacity:ctas?1:0,transform:ctas?"translateY(0)":"translateY(20px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)",display:"flex",gap:14,flexWrap:"wrap",justifyContent:isMobile?"center":"flex-start"}}>
            <a href="#comprar" style={{textDecoration:"none",background:"linear-gradient(90deg,var(--black) 40%,rgba(255,204,102,0.25) 50%,var(--black) 60%)",backgroundSize:"300% auto",color:"var(--white)",padding:"16px 38px",fontFamily:"var(--sans)",fontSize:12,fontWeight:600,letterSpacing:"0.12em",textTransform:"uppercase",animation:"shimmerBtn 2.8s linear infinite"}}>Reservar mi TapTunes</a>
            <a href="#como-funciona" style={{textDecoration:"none",background:"transparent",color:"var(--black)",padding:"16px 38px",fontFamily:"var(--sans)",fontSize:12,fontWeight:600,letterSpacing:"0.12em",textTransform:"uppercase",border:"1px solid rgba(26,26,26,0.5)",transition:"all 0.3s ease"}} onMouseEnter={e=>{e.currentTarget.style.background="var(--black)";e.currentTarget.style.color="var(--white)";}} onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color="var(--black)";}}>Ver cómo funciona</a>
          </div>
          <div style={{marginTop:36,opacity:play?1:0,transition:"opacity 0.8s ease 0.4s",display:"flex",alignItems:"center",gap:14,justifyContent:isMobile?"center":"flex-start"}}><span style={{fontFamily:"var(--sans)",fontSize:10,color:"var(--caramel)",letterSpacing:"0.12em",fontWeight:600}}>REPRODUCIENDO</span><AudioWaveform bars={22} color="var(--caramel)" height={32} active={play}/></div>
        </div>
        <div ref={tRef} style={{display:"flex",flexDirection:"column",alignItems:"center",willChange:"transform",opacity:tt?1:0,transform:tt?"scale(1)":"scale(0.85)",transition:"opacity 1s cubic-bezier(0.4,0,0.2,1),transform 1.2s cubic-bezier(0.34,1.28,0.64,1)"}}>
          <div style={{position:"relative",filter:play?"drop-shadow(0 0 40px rgba(255,204,102,0.35))":"drop-shadow(0 12px 40px rgba(0,0,0,0.14))",transition:"filter 1s ease"}}><Turntable size={isMobile?280:420} spinning={play} labelColor="#B8860B" glowIntensity={play?0.85:0.3} showControls={true} armPosition={play?"playing":"resting"} discVisible={disc} discAnimating={anim}/></div>
          <div style={{marginTop:20,display:"flex",alignItems:"center",gap:10,opacity:disc?1:0,transition:"opacity 0.6s ease 0.5s"}}><NfcWaves size={36} active={play}/><span style={{fontFamily:"var(--sans)",fontSize:10,fontWeight:600,letterSpacing:"0.14em",color:"var(--caramel)",textTransform:"uppercase"}}>{play?"NFC Detectado":"Acercá un disco"}</span></div>
        </div>
      </div>
    </section>
  );
}

function HowItWorks(){const[ref,vis]=useInView(0.12);const steps=[{num:"01",title:"Elegí tu disco",desc:"Cada disco representa una canción, una playlist o un momento especial.",Icon:IconDisc,color:"var(--burnt-orange)"},{num:"02",title:"Acercalo a TapTunes",desc:"La tecnología NFC identifica el disco al instante. Sin apps, sin complicaciones.",Icon:({size,color,animated})=>(<svg width={size} height={size} viewBox="0 0 40 40" fill="none">{[10,16,22].map((r,i)=>(<path key={i} d={`M20,20 m-${r},0 a${r},${r} 0 0,1 ${r*2},0`} stroke={color} strokeWidth="2" strokeLinecap="round" fill="none" style={animated?{animation:`strokeIn 0.8s ease-out ${i*0.2}s forwards`}:{}}/>))}<circle cx="20" cy="20" r="3" fill={color} opacity="0.7"/></svg>),color:"var(--caramel)"},{num:"03",title:"Reviví el momento",desc:"La música empieza, la luz se enciende. Escuchá, regalá o compartí recuerdos.",Icon:IconZap,color:"var(--olive)"}];
  return(<section id="como-funciona" ref={ref} style={{padding:"clamp(80px,12vw,160px) clamp(20px,5vw,80px)",maxWidth:1200,margin:"0 auto"}}><div style={{textAlign:"center",marginBottom:80,opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(36px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>Así de simple</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(32px,5vw,56px)",fontWeight:400,marginTop:14,lineHeight:1.15}}>Tres pasos.<br/><em style={{fontStyle:"italic"}}>Cero complicaciones.</em></h2></div><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:48}}>{steps.map((s,i)=>(<div key={i} style={{opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(48px)",transition:`all 0.85s cubic-bezier(0.4,0,0.2,1) ${0.15+i*0.18}s`,textAlign:"center",padding:"40px 28px"}}><div style={{width:88,height:88,borderRadius:"50%",margin:"0 auto 20px",border:`1.5px solid ${s.color}`,display:"flex",alignItems:"center",justifyContent:"center",transition:"transform 0.4s ease"}} onMouseEnter={e=>e.currentTarget.style.transform="scale(1.08)"} onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"}><s.Icon size={38} color={s.color} animated={vis}/></div><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:700,letterSpacing:"0.18em",color:"var(--caramel)"}}>{s.num}</span><h3 style={{fontFamily:"var(--serif)",fontSize:26,fontWeight:500,margin:"8px 0 14px"}}>{s.title}</h3><p style={{fontFamily:"var(--sans)",fontSize:14,color:"var(--warm-gray)",lineHeight:1.75}}>{s.desc}</p></div>))}</div></section>);
}

function Features(){const[ref,vis]=useInView(0.1);const ft=[{Icon:IconZap,title:"Reproducción instantánea",desc:"Acercá el disco y la música empieza.",span:2},{Icon:IconLight,title:"Luz ambiental LED",desc:"Iluminación cálida que crea atmósfera.",span:1},{Icon:IconDisc,title:"Diseño tocadiscos mini",desc:"Estética premium para cualquier espacio.",span:1},{Icon:IconUSB,title:"Carga USB-C",desc:"8 horas de reproducción por carga.",span:1},{Icon:IconChip,title:"128MB integrados",desc:"Tu música guardada, sin internet.",span:1},{Icon:IconDiscs,title:"9 discos incluidos",desc:"Cada disco, una canción o playlist.",span:2}];
  return(<section ref={ref} style={{background:"var(--black)",color:"var(--white)",position:"relative",overflow:"hidden"}}><div style={{position:"absolute",inset:0,pointerEvents:"none",background:"radial-gradient(ellipse at 20% 50%,rgba(55,40,10,0.4) 0%,transparent 60%),radial-gradient(ellipse at 80% 20%,rgba(20,20,50,0.3) 0%,transparent 60%)",opacity:0.8}}/><div style={{maxWidth:1200,margin:"0 auto",padding:"clamp(80px,12vw,160px) clamp(20px,5vw,80px)",position:"relative"}}><div style={{marginBottom:64,opacity:vis?1:0,transform:vis?"translateX(0)":"translateX(-32px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel-light)"}}>Características</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(32px,4.5vw,52px)",fontWeight:400,marginTop:14,lineHeight:1.2,maxWidth:480}}>Diseñado para<br/><em style={{fontStyle:"italic",color:"var(--led-warm)"}}>sentir la música.</em></h2></div><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:2,background:"rgba(255,255,255,0.04)"}}>{ft.map((f,i)=>(<div key={i} style={{gridColumn:f.span===2?"span 2":"span 1",padding:"clamp(24px,3.5vw,40px)",background:"var(--black-soft)",opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(28px)",transition:`all 0.65s cubic-bezier(0.4,0,0.2,1) ${0.1+i*0.1}s`,cursor:"default"}} onMouseEnter={e=>{e.currentTarget.style.background="rgba(255,255,255,0.04)";e.currentTarget.style.outline="1px solid rgba(212,168,67,0.25)";}} onMouseLeave={e=>{e.currentTarget.style.background="var(--black-soft)";e.currentTarget.style.outline="none";}}><div style={{marginBottom:16}}><f.Icon size={38} color="var(--white)" animated={vis}/></div><h4 style={{fontFamily:"var(--sans)",fontSize:13,fontWeight:600,marginBottom:8}}>{f.title}</h4><p style={{fontFamily:"var(--sans)",fontSize:12,color:"var(--warm-gray-light)",lineHeight:1.65}}>{f.desc}</p></div>))}</div></div></section>);
}

function Discos(){const[ref,vis]=useInView(0.1);const[hov,setHov]=useState(null);const[sel,setSel]=useState(null);const sz=typeof window!=="undefined"&&window.innerWidth<480?100:130;
  return(<section ref={ref} style={{padding:"clamp(80px,12vw,160px) clamp(20px,5vw,80px)",maxWidth:1200,margin:"0 auto"}}><div style={{textAlign:"center",marginBottom:72,opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(36px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>9 discos incluidos</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(32px,5vw,56px)",fontWeight:400,marginTop:14,lineHeight:1.15}}>Cada disco,<br/><em style={{fontStyle:"italic"}}>una historia.</em></h2><p style={{fontFamily:"var(--sans)",fontSize:15,color:"var(--warm-gray)",maxWidth:460,margin:"16px auto 0",lineHeight:1.7}}>Personalizá cada disco con la canción, playlist o recuerdo que quieras.</p></div><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(140px,1fr))",gap:"clamp(20px,3vw,36px)",maxWidth:820,margin:"0 auto"}}>{discs.map((d,i)=>{const isH=hov===d.id;const isS=sel===d.id;return(<div key={d.id}><div style={{opacity:vis?1:0,transform:vis?(isH?"translateY(-10px)":"translateY(0)"):"translateY(40px)",transition:`opacity 0.65s cubic-bezier(0.4,0,0.2,1) ${0.08+i*0.07}s,transform 0.4s cubic-bezier(0.34,1.28,0.64,1)`,textAlign:"center",cursor:"pointer"}} onMouseEnter={()=>setHov(d.id)} onMouseLeave={()=>setHov(null)} onClick={()=>setSel(isS?null:d.id)}><div style={{display:"inline-block",borderRadius:"50%",boxShadow:isH?`0 0 0 3px ${d.color}35,0 12px 32px rgba(0,0,0,0.12)`:"0 4px 16px rgba(0,0,0,0.06)",transition:"box-shadow 0.35s ease",padding:4,marginBottom:10}}><VinylDisc size={sz} color={d.color} number={String(d.id).padStart(2,"0")} spinning={isH}/></div><span style={{fontFamily:"var(--sans)",fontSize:12,fontWeight:600,display:"block",color:isH?d.color:"var(--black)",transition:"color 0.3s ease"}}>{d.name}</span><span style={{fontFamily:"var(--sans)",fontSize:11,color:"var(--warm-gray)",display:"block",marginTop:4,maxWidth:130,margin:"4px auto 0",opacity:isH?1:0,transform:isH?"translateY(0)":"translateY(-4px)",transition:"all 0.3s ease"}}>{d.desc}</span></div>{isS&&(<div style={{marginTop:12,padding:"16px 14px",background:"var(--white)",borderLeft:`3px solid ${d.color}`,boxShadow:"0 4px 20px rgba(0,0,0,0.06)",animation:"fadeInUp 0.3s ease"}}><p style={{fontFamily:"var(--sans)",fontSize:11,color:"var(--warm-gray)",lineHeight:1.6,marginBottom:10}}>{d.desc}</p><div style={{padding:"8px 10px",background:"var(--cream)",fontFamily:"var(--sans)",fontSize:10,color:"var(--warm-gray-light)",marginBottom:8}}>🎵 Asigná tu canción aquí</div><AudioWaveform bars={14} color={d.color} height={24} active={true}/></div>)}</div>);})}</div></section>);
}

function Personalizacion(){const[ref,vis]=useInView();return(<section ref={ref} style={{padding:"clamp(80px,12vw,140px) clamp(20px,5vw,80px)",background:"var(--cream-dark)"}}><div style={{maxWidth:900,margin:"0 auto",textAlign:"center",opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(36px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>Personalización</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(32px,5vw,48px)",fontWeight:400,margin:"14px 0 20px",lineHeight:1.2}}>Tus canciones.<br/><em style={{fontStyle:"italic"}}>Tus discos. Tu historia.</em></h2><p style={{fontFamily:"var(--sans)",fontSize:15,color:"var(--warm-gray)",lineHeight:1.8,maxWidth:540,margin:"0 auto 48px"}}>Conectá TapTunes a tu computadora por USB-C, cargá tus archivos de audio y asigná cada canción a un disco.</p><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:20,maxWidth:700,margin:"0 auto"}}>{[{label:"Canción favorita",desc:"Cargá el MP3 de cualquier tema.",icon:<IconZap size={28} color="var(--caramel)"/>},{label:"Playlist temática",desc:"Varios temas en un solo disco.",icon:<IconDiscs size={28} color="var(--caramel)"/>},{label:"Audio personalizado",desc:"Mensaje de voz, grabación especial.",icon:<IconLight size={28} color="var(--caramel)"/>}].map((item,i)=>(<div key={i} style={{padding:"28px 24px",background:"var(--white)",boxShadow:"0 2px 16px rgba(0,0,0,0.04)",opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(28px)",transition:`all 0.65s cubic-bezier(0.4,0,0.2,1) ${0.2+i*0.14}s`,borderTop:"2px solid transparent"}} onMouseEnter={e=>e.currentTarget.style.borderTopColor="var(--caramel)"} onMouseLeave={e=>e.currentTarget.style.borderTopColor="transparent"}><div style={{marginBottom:12}}>{item.icon}</div><h4 style={{fontFamily:"var(--sans)",fontSize:12,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",marginBottom:8}}>{item.label}</h4><p style={{fontFamily:"var(--sans)",fontSize:13,color:"var(--warm-gray)",lineHeight:1.65}}>{item.desc}</p></div>))}</div></div></section>);}

function CasosDeUso(){const[ref,vis]=useInView();return(<section ref={ref} style={{padding:"clamp(80px,12vw,140px) clamp(20px,5vw,80px)",maxWidth:1200,margin:"0 auto"}}><div style={{textAlign:"center",marginBottom:48,opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(36px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>Para cada momento</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(32px,5vw,48px)",fontWeight:400,marginTop:14,lineHeight:1.2}}>El regalo que<br/><em style={{fontStyle:"italic"}}>reproduce recuerdos.</em></h2></div><div style={{display:"flex",flexWrap:"wrap",justifyContent:"center",gap:10}}>{useCases.map((uc,i)=>(<div key={i} style={{padding:"11px 22px",background:"var(--white)",border:"1px solid var(--cream-dark)",fontFamily:"var(--sans)",fontSize:13,fontWeight:500,opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(18px)",transition:`all 0.5s cubic-bezier(0.4,0,0.2,1) ${0.05+i*0.04}s`,cursor:"default"}} onMouseEnter={e=>{e.currentTarget.style.background="var(--black)";e.currentTarget.style.color="var(--white)";e.currentTarget.style.borderColor="var(--black)";}} onMouseLeave={e=>{e.currentTarget.style.background="var(--white)";e.currentTarget.style.color="var(--black)";e.currentTarget.style.borderColor="var(--cream-dark)";}}>{uc}</div>))}</div></section>);}

function Comprar(){const[ref,vis]=useInView(0.12);const[price,setPrice]=useState(0);const started=useRef(false);const isMobile=typeof window!=="undefined"&&window.innerWidth<768;
  useEffect(()=>{if(!vis||started.current)return;started.current=true;let c=0;const t=89,inc=t/(1100/16);const timer=setInterval(()=>{c=Math.min(c+inc,t);setPrice(Math.round(c));if(c>=t)clearInterval(timer);},16);return()=>clearInterval(timer);},[vis]);
  return(<section id="comprar" ref={ref} style={{padding:"clamp(80px,12vw,160px) clamp(20px,5vw,80px)",background:"var(--cream-dark)"}}><div style={{maxWidth:1000,margin:"0 auto",display:"grid",gridTemplateColumns:isMobile?"1fr":"1fr 1fr",gap:64,alignItems:"center"}}><div style={{opacity:vis?1:0,transform:vis?"translateX(0)":"translateX(-40px)",transition:"all 0.9s cubic-bezier(0.4,0,0.2,1)",display:"flex",flexDirection:"column",alignItems:"center"}}><div style={{position:"relative"}}><div style={{position:"absolute",inset:-20,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,204,102,0.18) 0%,transparent 70%)",animation:"breathe 4s ease-in-out infinite"}}/><Turntable size={isMobile?260:340} spinning={vis} labelColor="#B8860B" glowIntensity={0.75} showControls={true} armPosition="playing" discVisible={true}/></div><div style={{display:"flex",justifyContent:"center",gap:8,marginTop:28,flexWrap:"wrap"}}>{discs.map(d=>(<div key={d.id} style={{width:28,height:28,borderRadius:"50%",background:d.color,border:"2.5px solid var(--cream-dark)",boxShadow:"0 2px 6px rgba(0,0,0,0.12)",transition:"transform 0.2s ease"}} onMouseEnter={e=>e.currentTarget.style.transform="scale(1.25)"} onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"} title={d.name}/>))}</div></div><div style={{opacity:vis?1:0,transform:vis?"translateX(0)":"translateX(40px)",transition:"all 0.9s cubic-bezier(0.4,0,0.2,1) 0.2s"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>Preventa</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(28px,4vw,42px)",fontWeight:400,margin:"12px 0 8px",lineHeight:1.15}}>TapTunes™ Starter Kit</h2><p style={{fontFamily:"var(--sans)",fontSize:14,color:"var(--warm-gray)",lineHeight:1.7,marginBottom:28}}>Todo lo que necesitás para empezar a convertir tu música en recuerdos físicos.</p><div style={{marginBottom:32}}>{["1 reproductor TapTunes con speaker integrado","9 discos NFC personalizables","Cable USB-C para carga y transferencia","Guía de configuración rápida","Garantía de 90 días"].map((item,i)=>(<div key={i} style={{padding:"11px 0",borderBottom:"1px solid var(--cream)",fontFamily:"var(--sans)",fontSize:13,color:"var(--black-soft)",display:"flex",alignItems:"center",gap:12}}><span style={{color:"var(--caramel)",fontSize:10}}>✦</span>{item}</div>))}</div><div style={{marginBottom:32}}><div style={{display:"flex",alignItems:"baseline",gap:14}}><span style={{fontFamily:"var(--serif)",fontSize:42,fontWeight:500}}>USD {price}</span><span style={{fontFamily:"var(--sans)",fontSize:13,color:"var(--warm-gray)",textDecoration:"line-through"}}>USD 119</span></div><span style={{fontFamily:"var(--sans)",fontSize:11,color:"var(--olive)",fontWeight:600,letterSpacing:"0.05em"}}>PRECIO PREVENTA · ENVÍO GRATIS EN MONTEVIDEO</span></div><button style={{width:"100%",padding:"18px 40px",background:"linear-gradient(90deg,var(--black) 40%,rgba(255,204,102,0.3) 50%,var(--black) 60%)",backgroundSize:"300% auto",color:"var(--white)",border:"none",fontFamily:"var(--sans)",fontSize:13,fontWeight:600,letterSpacing:"0.12em",textTransform:"uppercase",cursor:"pointer",animation:"shimmerBtn 2.5s linear infinite"}} onClick={()=>{const el=document.getElementById("reserva-form");if(el)el.scrollIntoView({behavior:"smooth"});}}>Reservar mi TapTunes</button><div style={{display:"flex",justifyContent:"center",gap:24,marginTop:18}}>{["Compra segura","Garantía 90 días","Soporte WhatsApp"].map((t,i)=>(<span key={i} style={{fontFamily:"var(--sans)",fontSize:10,color:"var(--warm-gray)",fontWeight:500}}>{t}</span>))}</div></div></div></section>);
}

function ReservaForm(){const[ref,vis]=useInView();const[form,setForm]=useState({name:"",email:"",phone:"",discs:""});const[done,setDone]=useState(false);const inputStyle={width:"100%",padding:"14px 16px",border:"1px solid var(--cream-dark)",background:"var(--white)",fontFamily:"var(--sans)",fontSize:14,color:"var(--black)",outline:"none",transition:"border-color 0.3s ease,box-shadow 0.3s ease",borderRadius:0};
  if(done)return(<section id="reserva-form" style={{padding:"clamp(80px,12vw,140px) clamp(20px,5vw,80px)",textAlign:"center"}}><div style={{maxWidth:520,margin:"0 auto",padding:"56px 48px",background:"var(--white)",boxShadow:"0 8px 40px rgba(0,0,0,0.05)",animation:"fadeInUp 0.6s ease"}}><div style={{width:64,height:64,borderRadius:"50%",margin:"0 auto 24px",background:"var(--olive)",display:"flex",alignItems:"center",justifyContent:"center"}}><svg width="28" height="28" viewBox="0 0 28 28" fill="none"><polyline points="6,14 11,20 22,9" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg></div><h3 style={{fontFamily:"var(--serif)",fontSize:28,fontWeight:400,marginBottom:14}}>Reserva recibida</h3><p style={{fontFamily:"var(--sans)",fontSize:14,color:"var(--warm-gray)",lineHeight:1.75,maxWidth:380,margin:"0 auto"}}>Gracias, <strong>{form.name}</strong>. Te contactaremos a <strong>{form.email}</strong> con los detalles de tu pedido.</p></div></section>);
  return(<section id="reserva-form" ref={ref} style={{padding:"clamp(80px,12vw,140px) clamp(20px,5vw,80px)"}}><div style={{maxWidth:520,margin:"0 auto",opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(36px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><div style={{textAlign:"center",marginBottom:40}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>Reservá el tuyo</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(28px,4vw,40px)",fontWeight:400,marginTop:12}}>Completá tu reserva</h2><p style={{fontFamily:"var(--sans)",fontSize:14,color:"var(--warm-gray)",marginTop:12,lineHeight:1.7}}>Dejá tus datos y te contactamos para coordinar el pago y envío.</p></div><div style={{display:"flex",flexDirection:"column",gap:16}}>{[{key:"name",label:"NOMBRE COMPLETO",placeholder:"Tu nombre",type:"text"},{key:"email",label:"EMAIL",placeholder:"tu@email.com",type:"email"},{key:"phone",label:"TELÉFONO / WHATSAPP",placeholder:"+598 ...",type:"tel"}].map(f=>(<div key={f.key}><label style={{fontFamily:"var(--sans)",fontSize:10,fontWeight:600,letterSpacing:"0.15em",color:"var(--warm-gray)",display:"block",marginBottom:6}}>{f.label}</label><input type={f.type} placeholder={f.placeholder} value={form[f.key]} onChange={e=>setForm({...form,[f.key]:e.target.value})} style={inputStyle} onFocus={e=>{e.target.style.borderColor="var(--caramel)";e.target.style.boxShadow="0 0 0 3px rgba(184,134,11,0.08)";}} onBlur={e=>{e.target.style.borderColor="var(--cream-dark)";e.target.style.boxShadow="none";}}/></div>))}<div><label style={{fontFamily:"var(--sans)",fontSize:10,fontWeight:600,letterSpacing:"0.15em",color:"var(--warm-gray)",display:"block",marginBottom:6}}>CANCIONES O PERSONALIZACIÓN (OPCIONAL)</label><textarea placeholder="Contanos qué canciones o playlists te gustaría cargar..." value={form.discs} onChange={e=>setForm({...form,discs:e.target.value})} rows={3} style={{...inputStyle,resize:"vertical",minHeight:88}} onFocus={e=>{e.target.style.borderColor="var(--caramel)";e.target.style.boxShadow="0 0 0 3px rgba(184,134,11,0.08)";}} onBlur={e=>{e.target.style.borderColor="var(--cream-dark)";e.target.style.boxShadow="none";}}/></div><button onClick={()=>{if(form.name&&form.email&&form.phone)setDone(true);}} disabled={!form.name||!form.email||!form.phone} style={{width:"100%",padding:"18px",background:"var(--black)",color:"var(--white)",border:"none",fontFamily:"var(--sans)",fontSize:13,fontWeight:600,letterSpacing:"0.12em",textTransform:"uppercase",cursor:"pointer",transition:"background 0.3s ease",marginTop:8,opacity:(!form.name||!form.email||!form.phone)?0.38:1}} onMouseEnter={e=>{if(form.name&&form.email&&form.phone)e.currentTarget.style.background="var(--caramel)";}} onMouseLeave={e=>e.currentTarget.style.background="var(--black)"}>Confirmar reserva</button><p style={{fontFamily:"var(--sans)",fontSize:11,color:"var(--warm-gray)",textAlign:"center",lineHeight:1.65}}>Al reservar aceptás que te contactemos por email o WhatsApp. No se cobra hasta confirmar tu pedido.</p></div></div></section>);
}

function FAQ(){const[ref,vis]=useInView();const[open,setOpen]=useState(null);return(<section ref={ref} style={{padding:"clamp(80px,12vw,140px) clamp(20px,5vw,80px)",background:"var(--cream-dark)"}}><div style={{maxWidth:720,margin:"0 auto"}}><div style={{textAlign:"center",marginBottom:56,opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(36px)",transition:"all 0.8s cubic-bezier(0.4,0,0.2,1)"}}><span style={{fontFamily:"var(--sans)",fontSize:11,fontWeight:600,letterSpacing:"0.2em",textTransform:"uppercase",color:"var(--caramel)"}}>Preguntas frecuentes</span><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(28px,4vw,42px)",fontWeight:400,marginTop:12}}>Todo lo que necesitás saber</h2></div><div>{faqs.map((faq,i)=>(<div key={i} style={{borderBottom:"1px solid rgba(26,26,26,0.08)",opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(18px)",transition:`all 0.55s cubic-bezier(0.4,0,0.2,1) ${0.08+i*0.055}s`}}><button onClick={()=>setOpen(open===i?null:i)} style={{width:"100%",padding:"20px 0",background:"none",border:"none",cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center",fontFamily:"var(--sans)",fontSize:14,fontWeight:500,color:"var(--black)",textAlign:"left",transition:"transform 0.2s ease,color 0.2s ease"}} onMouseEnter={e=>{e.currentTarget.style.transform="translateX(4px)";e.currentTarget.style.color="var(--caramel)";}} onMouseLeave={e=>{e.currentTarget.style.transform="translateX(0)";e.currentTarget.style.color="var(--black)";}}><span>{faq.q}</span><span style={{fontSize:20,flexShrink:0,marginLeft:16,color:"var(--caramel)",transform:open===i?"rotate(45deg)":"rotate(0deg)",transition:"transform 0.35s cubic-bezier(0.4,0,0.2,1)",fontWeight:300}}>+</span></button><div style={{maxHeight:open===i?220:0,overflow:"hidden",transition:"max-height 0.45s cubic-bezier(0.4,0,0.2,1)"}}><div style={{padding:"4px 0 24px 20px",borderLeft:open===i?"2px solid var(--caramel)":"2px solid transparent",transition:"border-color 0.3s ease 0.15s"}}><p style={{fontFamily:"var(--sans)",fontSize:13,color:"var(--warm-gray)",lineHeight:1.75}}>{faq.a}</p></div></div></div>))}</div></div></section>);}

function FinalCTA(){const[ref,vis]=useInView(0.12);const isMobile=typeof window!=="undefined"&&window.innerWidth<768;return(<section ref={ref} style={{padding:"clamp(100px,15vw,200px) clamp(20px,5vw,80px)",textAlign:"center",position:"relative",overflow:"hidden",background:"linear-gradient(175deg,var(--black) 0%,#1E1810 55%,var(--cream-dark) 100%)"}}><div style={{position:"absolute",top:"30%",left:"50%",transform:"translate(-50%,-50%)",width:700,height:700,borderRadius:"50%",background:"radial-gradient(circle,rgba(255,204,102,0.12) 0%,transparent 70%)",animation:"breathe 6s ease-in-out infinite",pointerEvents:"none"}}/>{!isMobile&&(<div style={{position:"absolute",right:"8%",top:"50%",transform:"translateY(-50%)",opacity:vis?0.7:0,transition:"opacity 1s ease 0.5s",animation:"floatUp 5s ease-in-out infinite",filter:"drop-shadow(0 20px 40px rgba(255,204,102,0.2))"}}><VinylDisc size={160} color="#B8860B" number="01" spinning={vis}/></div>)}<div style={{position:"relative",zIndex:1,opacity:vis?1:0,transform:vis?"translateY(0)":"translateY(40px)",transition:"all 0.9s cubic-bezier(0.4,0,0.2,1)"}}><h2 style={{fontFamily:"var(--serif)",fontSize:"clamp(32px,6vw,68px)",fontWeight:400,lineHeight:1.12,maxWidth:680,margin:"0 auto 28px",color:"var(--white)"}}>Convertí tus canciones en<br/><em style={{fontStyle:"italic",color:"var(--led-warm)"}}>recuerdos físicos.</em></h2><p style={{fontFamily:"var(--sans)",fontSize:15,color:"rgba(255,255,255,0.55)",maxWidth:440,margin:"0 auto 48px",lineHeight:1.75}}>Música, memoria y luz en un solo objeto. Reservá tu TapTunes hoy.</p><a href="#comprar" style={{textDecoration:"none",display:"inline-block",background:"linear-gradient(90deg,var(--caramel) 40%,var(--caramel-light) 50%,var(--caramel) 60%)",backgroundSize:"300% auto",color:"var(--white)",padding:"18px 52px",fontFamily:"var(--sans)",fontSize:13,fontWeight:600,letterSpacing:"0.12em",textTransform:"uppercase",animation:"shimmerBtn 2.5s linear infinite",marginBottom:40}}>Reservar TapTunes</a><div style={{display:"flex",justifyContent:"center",opacity:0.5}}><AudioWaveform bars={32} color="rgba(255,216,155,0.7)" height={40} active={vis}/></div></div></section>);}

function Footer(){return(<footer style={{padding:"44px clamp(20px,5vw,80px) 28px",borderTop:"1px solid rgba(26,26,26,0.07)",background:"var(--cream)"}}><div style={{maxWidth:1200,margin:"0 auto",display:"flex",flexWrap:"wrap",justifyContent:"space-between",alignItems:"center",gap:20}}><div style={{display:"flex",alignItems:"center",gap:8}}><svg width="22" height="22" viewBox="0 0 22 22" fill="none"><circle cx="11" cy="11" r="9.5" stroke="var(--black)" strokeWidth="1.5"/><circle cx="11" cy="11" r="4.5" stroke="var(--black)" strokeWidth="1"/><circle cx="11" cy="11" r="1.5" fill="var(--black)"/></svg><span style={{fontFamily:"var(--sans)",fontWeight:700,fontSize:13,letterSpacing:"0.12em"}}>TAPTUNES™</span></div><div style={{display:"flex",gap:24}}>{["Instagram","TikTok","WhatsApp"].map(s=>(<span key={s} style={{fontFamily:"var(--sans)",fontSize:12,color:"var(--warm-gray)",cursor:"pointer",transition:"color 0.25s ease"}} onMouseEnter={e=>e.currentTarget.style.color="var(--caramel)"} onMouseLeave={e=>e.currentTarget.style.color="var(--warm-gray)"}>{s}</span>))}</div><span style={{fontFamily:"var(--sans)",fontSize:11,color:"var(--warm-gray-light)"}}>© 2026 TapTunes™ · Montevideo, Uruguay</span></div></footer>);}

export default function TapTunesLanding(){const[scrolled,setScrolled]=useState(false);useEffect(()=>{const o=()=>setScrolled(window.scrollY>60);window.addEventListener("scroll",o,{passive:true});return()=>window.removeEventListener("scroll",o);},[]);return(<div style={{background:"var(--cream)",minHeight:"100vh"}}><ScrollProgressBar/><Navbar scrolled={scrolled}/><Hero/><WaveDivider toColor="var(--cream)"/><HowItWorks/><WaveDivider toColor="var(--black)"/><Features/><WaveDivider toColor="var(--cream)"/><Discos/><Personalizacion/><CasosDeUso/><WaveDivider toColor="var(--cream-dark)"/><Comprar/><ReservaForm/><FAQ/><FinalCTA/><Footer/></div>);}
